/**
 * DriveLedger — Static SEO Metadata Prerenderer
 *
 * Zero-cost build-time static HTML metadata prerenderer.
 * Ingests dist/index.html generated by Vite, resolves route-specific metadata
 * (<title>, <meta name="description">, <link rel="canonical">, OpenGraph, Twitter tags),
 * and emits pre-rendered static HTML entry files across all programmatic SEO routes.
 */

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

import { VEHICLE_PRESETS } from '../src/data/vehiclePresets.js';
import { GUIDES_DATA } from '../src/data/guidesData.js';
import {
  generateFullVehicleObdMatrix,
  PROGRAMMATIC_COMPARE_PAIRS,
  MILEAGE_BRACKET_SLUGS,
} from '../src/data/seoMatrixData.js';
import { OBD_CODES } from '../src/data/obdCodes.js';
import {
  calculateTcoProjection,
  evaluateComponentHealth,
  MAINTENANCE_COMPONENTS,
} from '../src/data/maintenanceData.js';
import { MONETIZATION_CONFIG } from '../src/config/monetizationConfig.js';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
export const ROOT_DIR = path.resolve(__dirname, '..');
export const DIST_DIR = path.resolve(ROOT_DIR, 'dist');

export const SITE_ORIGIN = `https://${MONETIZATION_CONFIG.domain || 'mydriveledger.com'}`;

/**
 * Escapes unsafe HTML characters into safe XML/HTML entities.
 */
export function escapeHtml(unsafe) {
  if (unsafe == null) return '';
  return String(unsafe)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

/**
 * Resolves a route path to its deterministic destination file path under distDir.
 */
export function routePathToDistFile(distDir, routePath) {
  const clean = (routePath || '/').split('?')[0].split('#')[0].trim();
  const stripped = clean.replace(/^\/+|\/+$/g, '');
  if (!stripped) {
    return path.join(distDir, 'index.html');
  }
  const segments = stripped.split('/');
  return path.join(distDir, ...segments, 'index.html');
}

/**
 * Computes baseline 5-Year TCO and Reliability Score for a given vehicle preset.
 */
export function computePresetTelemetry(preset) {
  const safePreset = preset || VEHICLE_PRESETS[0];

  const tco = calculateTcoProjection({
    purchasePriceUsd: safePreset.purchasePriceUsd,
    odometerMiles: safePreset.defaultOdometerMiles,
    annualDistanceMiles: safePreset.annualDistanceMiles,
    mpgUs: safePreset.mpgUs,
    isEv: safePreset.isEv,
    fuelPriceUsdGal: safePreset.defaultFuelPriceUsdGal,
    annualInsuranceUsd: safePreset.annualInsuranceUsd,
    baseAnnualMaintenanceUsd: safePreset.baseAnnualMaintenanceUsd,
    maintenanceWearFactor: safePreset.maintenanceWearFactor,
    downPaymentPct: 20,
    aprPct: 6.2,
    loanTermMonths: 60,
    horizonYears: 5,
    residualCurve10Yr: safePreset.residualCurve10Yr,
  });

  const physicalOdometerMiles = Math.max(38000, safePreset.defaultOdometerMiles || 58000);
  const relevantComponents = MAINTENANCE_COMPONENTS.filter((comp) =>
    comp.applicablePowertrains.includes(safePreset.powertrain || 'diesel')
  );

  const evaluated = relevantComponents.map((comp) =>
    evaluateComponentHealth({
      component: comp,
      physicalOdometerMiles,
      urbanTripSharePct: 45,
      oilIntervalId: 'standard',
      serviceHistoryId: 'verified',
      transmissionId: safePreset.transmission || 'dct-dsg',
    })
  );

  let reliabilityScore = 75;
  if (evaluated.length > 0) {
    const avgWear = evaluated.reduce((acc, h) => acc + h.wearPctOfCritical, 0) / evaluated.length;
    const criticalCount = evaluated.filter((h) => h.status === 'CRITICAL').length;
    const warningCount = evaluated.filter((h) => h.status === 'WARNING').length;
    const penalty = criticalCount * 14 + warningCount * 6;
    const raw = 100 - avgWear * 0.45 - penalty;
    reliabilityScore = Math.min(95, Math.max(18, Math.round(raw)));
  }

  return {
    total5YrTcoUsd: tco.totalEconomicCostUsd,
    monthlyTcoUsd: tco.monthlyEconomicCostUsd,
    costPerMileUsd: tco.costPerMileUsd,
    depreciation5YrUsd: tco.totalDepreciationUsd,
    reliabilityScore,
    odometerMiles: physicalOdometerMiles,
  };
}

/**
 * Idempotently injects or replaces route-specific <title>, <meta name="description">,
 * <link rel="canonical">, OpenGraph tags, and Twitter tags into the HTML template.
 */
export function injectRouteMetadata(templateHtml, { title, description, canonicalUrl }) {
  const escapedTitle = escapeHtml(title);
  const escapedDescription = escapeHtml(description);
  const escapedCanonicalUrl = escapeHtml(canonicalUrl);

  let html = templateHtml;

  // 1. Title replacement / injection
  const titleRegex = /<title\b[^>]*>[\s\S]*?<\/title>/i;
  const newTitleTag = `<title>${escapedTitle}</title>`;
  if (titleRegex.test(html)) {
    html = html.replace(titleRegex, newTitleTag);
  } else {
    html = html.replace(/<head\b[^>]*>/i, (m) => `${m}\n  ${newTitleTag}`);
  }

  // 2. Meta description replacement / injection (multiline-safe)
  const descRegex = /<meta\s+[^>]*name=["']description["'][^>]*>/i;
  const newDescTag = `<meta name="description" content="${escapedDescription}" />`;
  if (descRegex.test(html)) {
    html = html.replace(descRegex, newDescTag);
  } else {
    html = html.replace(/<\/title>/i, (m) => `${m}\n  ${newDescTag}`);
  }

  // 3. Canonical link replacement / injection
  const canonicalRegex = /<link\s+[^>]*rel=["']canonical["'][^>]*>/i;
  const newCanonicalTag = `<link rel="canonical" href="${escapedCanonicalUrl}" />`;
  const hasCanonical = canonicalRegex.test(html);
  if (hasCanonical) {
    html = html.replace(canonicalRegex, newCanonicalTag);
  }

  // 4. Upsert OpenGraph & Twitter tags
  const socialMetaTags = [
    { type: 'property', name: 'og:title', content: escapedTitle },
    { type: 'property', name: 'og:description', content: escapedDescription },
    { type: 'property', name: 'og:url', content: escapedCanonicalUrl },
    { type: 'property', name: 'og:type', content: 'website' },
    { type: 'property', name: 'og:site_name', content: 'DriveLedger' },
    { type: 'name', name: 'twitter:card', content: 'summary_large_image' },
    { type: 'name', name: 'twitter:title', content: escapedTitle },
    { type: 'name', name: 'twitter:description', content: escapedDescription },
  ];

  const tagsToAppend = [];

  for (const tag of socialMetaTags) {
    const attr = tag.type;
    const pattern = new RegExp(`<meta\\s+[^>]*${attr}=["']${tag.name}["'][^>]*>`, 'i');
    const replacement = `<meta ${attr}="${tag.name}" content="${tag.content}" />`;
    if (pattern.test(html)) {
      html = html.replace(pattern, replacement);
    } else {
      tagsToAppend.push(replacement);
    }
  }

  if (tagsToAppend.length > 0) {
    const insertionBlock = tagsToAppend.join('\n  ');
    if (hasCanonical) {
      html = html.replace(newCanonicalTag, `${newCanonicalTag}\n  ${insertionBlock}`);
    } else {
      html = html.replace(/<\/head>/i, `  ${insertionBlock}\n</head>`);
    }
  }

  return html;
}

/**
 * Enumerates all static SEO routes across core, guides, vehicle presets, comparisons, and OBD dossiers.
 */
export function collectAllSeoRoutes(options = {}) {
  const { includeAllObd = false } = options;
  const routes = [];
  const addedPaths = new Set();

  function addRoute(route) {
    const cleanPath = route.path.split('?')[0].split('#')[0].replace(/\/+$/, '') || '/';
    if (addedPaths.has(cleanPath)) return;
    addedPaths.add(cleanPath);
    routes.push({
      ...route,
      path: cleanPath,
    });
  }

  // 1. Core and Legal Routes (16 routes)
  const CORE_ROUTES = [
    {
      path: '/tco',
      title: '5-Year True Cost to Own (TCO) Calculator | DriveLedger',
      description:
        'Calculate 5-year ownership costs, non-linear depreciation curves, financing interest, fuel, insurance, and scheduled maintenance for any vehicle.',
      canonicalUrl: `${SITE_ORIGIN}/tco`,
    },
    {
      path: '/risk-matrix',
      title: 'Powertrain Maintenance Risk Matrix & Reliability Score | DriveLedger',
      description:
        'Inspect upcoming maintenance horizons, thermodynamic urban wear penalties, and known powertrain defects across 179 vehicle configurations.',
      canonicalUrl: `${SITE_ORIGIN}/risk-matrix`,
    },
    {
      path: '/obd-estimator',
      title: 'OBD-II Diagnostic Trouble Code Repair Cost Estimator | DriveLedger',
      description:
        'Lookup diagnostic trouble codes (DTC), compare DIY vs Independent vs Dealership repair prices, and run first-principles live PID tests.',
      canonicalUrl: `${SITE_ORIGIN}/obd-estimator`,
    },
    {
      path: '/compare',
      title: 'Head-to-Head Vehicle Cost & Reliability Comparator | DriveLedger',
      description:
        'Compare any two vehicles side-by-side: 5-year TCO break-even crossover trajectory, true running costs, and known reliability flaws.',
      canonicalUrl: `${SITE_ORIGIN}/compare`,
    },
    {
      path: '/checklist',
      title: 'Pre-Purchase Inspection (PPI) Checklist & Defect Flagging | DriveLedger',
      description:
        'Master the used car pre-purchase inspection: cold-start protocols, fluid condition tests, diagnostic scans, and printable PDF inspection reports.',
      canonicalUrl: `${SITE_ORIGIN}/checklist`,
    },
    {
      path: '/guides',
      title: 'Buyer Guides & Automotive Due Diligence Insights | DriveLedger',
      description:
        'In-depth used car buyer guides, pre-purchase inspection protocols, and long-term ownership cost analyses written by master automotive technicians.',
      canonicalUrl: `${SITE_ORIGIN}/guides`,
    },
    {
      path: '/about',
      title: 'About DriveLedger — Independent Car Cost & Reliability Analytics',
      description:
        'DriveLedger is an independent automotive engineering and financial analytics platform. Learn about our actuarial depreciation curves, mileage risk weighting, and regional labor rates.',
      canonicalUrl: `${SITE_ORIGIN}/about`,
    },
    {
      path: '/contact',
      title: 'Contact DriveLedger — Editorial, Engineering & Legal Desk',
      description:
        'Contact the DriveLedger automotive engineering team for calculation inquiries, catalog corrections, or data protection assistance.',
      canonicalUrl: `${SITE_ORIGIN}/contact`,
    },
    {
      path: '/methodology',
      title: 'Automotive Engineering & Cost Methodology | DriveLedger',
      description:
        'Mathematical models, logarithmic depreciation formulas, Bayesian OBD-II probability, and actuarial data sources powering the DriveLedger platform.',
      canonicalUrl: `${SITE_ORIGIN}/methodology`,
    },
    {
      path: '/reviews',
      title: 'Owner Reviews & Repair Cost Benchmarks | DriveLedger',
      description:
        'Compare real-world repair shop quotes against independent parts and labor benchmarks, and read verified owner maintenance notes.',
      canonicalUrl: `${SITE_ORIGIN}/reviews`,
    },
    {
      path: '/privacy',
      title: 'Privacy Policy & Telemetry Data Governance | DriveLedger',
      description:
        'DriveLedger Privacy Policy: European GDPR, UK GDPR, and US state regulations (CCPA/CPRA/VCDPA/CPA/CTDPA) compliance, Google AdSense (ca-pub-6581535125716295) disclosures, and telemetry governance.',
      canonicalUrl: `${SITE_ORIGIN}/privacy`,
    },
    {
      path: '/terms',
      title: 'Terms of Service, Liability Shield & Disclaimers | DriveLedger',
      description:
        'DriveLedger Terms of Service: workshop safety waiver, statistical depreciation disclaimers, and nominative trademark fair use notices.',
      canonicalUrl: `${SITE_ORIGIN}/terms`,
    },
    {
      path: '/cookies',
      title: 'Cookie Policy, Local Storage & Consent Governance | DriveLedger',
      description:
        'DriveLedger Cookie Policy: First-party local storage, Google AdSense (ca-pub-6581535125716295) DoubleClick advertising cookies, IAB TCF v2.2 compliance, and opt-out controls.',
      canonicalUrl: `${SITE_ORIGIN}/cookies`,
    },
    {
      path: '/disclaimer',
      title: 'Comprehensive Automotive & Financial Disclaimer | DriveLedger',
      description:
        'DriveLedger Liability Disclaimer: Statistical financial estimates, workshop safety waivers, and nominative fair use declarations.',
      canonicalUrl: `${SITE_ORIGIN}/disclaimer`,
    },
    {
      path: '/affiliate-disclosure',
      title: 'FTC Affiliate Disclosure & Editorial Independence | DriveLedger',
      description:
        'DriveLedger FTC 16 CFR Part 255 compliance, Amazon Associates program disclosure, and algorithmic firewall guarantees.',
      canonicalUrl: `${SITE_ORIGIN}/affiliate-disclosure`,
    },
    {
      path: '/do-not-sell',
      title: 'Do Not Sell or Share My Personal Information | DriveLedger',
      description:
        'Exercise your US state privacy rights under CCPA, CPRA, VCDPA, CPA, and CTDPA to opt out of the sale or sharing of personal information for cross-context behavioral advertising.',
      canonicalUrl: `${SITE_ORIGIN}/do-not-sell`,
    },
  ];

  for (const item of CORE_ROUTES) {
    addRoute(item);
  }

  // 2. Editorial Guides (6 guides)
  for (const guide of GUIDES_DATA) {
    addRoute({
      path: `/guides/${guide.slug}`,
      title: guide.metaTitle || `${guide.title} | DriveLedger`,
      description: guide.metaDescription || guide.summary,
      canonicalUrl: `${SITE_ORIGIN}/guides/${guide.slug}`,
    });
  }

  // 3. Vehicle Presets & Mileage Brackets (179 presets × 6 = 1,074 routes)
  const telemetryMap = new Map();
  for (const preset of VEHICLE_PRESETS) {
    telemetryMap.set(preset.id, computePresetTelemetry(preset));
  }

  const brackets = Object.values(MILEAGE_BRACKET_SLUGS);

  for (const preset of VEHICLE_PRESETS) {
    const tel = telemetryMap.get(preset.id);

    // /tco/:id
    addRoute({
      path: `/tco/${preset.id}`,
      title: `${preset.name} 5-Year True Cost to Own & Depreciation | DriveLedger`,
      description: `${preset.name} (${preset.engineCode}) 5-year True Cost to Own is projected at $${tel.total5YrTcoUsd.toLocaleString()} ($${tel.monthlyTcoUsd}/mo or $${tel.costPerMileUsd}/mi), including $${tel.depreciation5YrUsd.toLocaleString()} non-linear depreciation and maintenance reserves.`,
      canonicalUrl: `${SITE_ORIGIN}/tco/${preset.id}`,
    });

    // /risk-matrix/:id
    addRoute({
      path: `/risk-matrix/${preset.id}`,
      title: `${preset.name} Reliability Score & Maintenance Risk Matrix | DriveLedger`,
      description: `${preset.name} achieves a ${tel.reliabilityScore}/100 Engineering Reliability Score at ${tel.odometerMiles.toLocaleString()} miles. Inspect critical wear horizons, thermodynamic urban duty penalties, and known defects (${preset.criticalDefectTag || 'Powertrain Telemetry'}).`,
      canonicalUrl: `${SITE_ORIGIN}/risk-matrix/${preset.id}`,
    });

    // /checklist/:id
    addRoute({
      path: `/checklist/${preset.id}`,
      title: `Pre-Purchase Inspection Checklist (PPI) – ${preset.name} | DriveLedger`,
      description: `On-site used car inspection checklist for ${preset.name} (${preset.engineCode}): critical known flaws, engine bay and chassis inspection, OBD-II diagnostics, and printable PDF report.`,
      canonicalUrl: `${SITE_ORIGIN}/checklist/${preset.id}`,
    });

    // /risk-matrix/:id/:bracketSlug (60k-miles, 100k-miles, 150k-miles)
    for (const bracket of brackets) {
      addRoute({
        path: `/risk-matrix/${preset.id}/${bracket.slug}`,
        title: `${preset.name} at ${bracket.label}: Reliability Risk & Maintenance Costs | DriveLedger`,
        description: `Buying or owning a ${preset.name} (${preset.engineCode}) at ${bracket.label}? Inspect imminent timing, transmission, DPF, and suspension failure probabilities, 12-month repair reserves, and OEM vs Preventative service schedules.`,
        canonicalUrl: `${SITE_ORIGIN}/risk-matrix/${preset.id}/${bracket.slug}`,
      });
    }
  }

  // 4. Head-to-Head Comparisons (800 matchups)
  const presetMap = new Map(VEHICLE_PRESETS.map((p) => [p.id, p]));
  for (const matchup of PROGRAMMATIC_COMPARE_PAIRS) {
    const presetA = presetMap.get(matchup.idA);
    const presetB = presetMap.get(matchup.idB);
    const telA = presetA ? telemetryMap.get(presetA.id) : null;
    const telB = presetB ? telemetryMap.get(presetB.id) : null;

    let title = `${matchup.title} | DriveLedger`;
    let description = `Compare ${matchup.title}: 5-year TCO break-even crossover trajectory, true running costs, and known reliability flaws.`;

    if (presetA && presetB && telA && telB) {
      const delta5Yr = Math.abs(telA.total5YrTcoUsd - telB.total5YrTcoUsd);
      const cheaperName =
        telB.total5YrTcoUsd < telA.total5YrTcoUsd ? presetB.name : presetA.name;
      title = `${presetA.name} vs ${presetB.name}: 5-Year TCO & Reliability Comparison | DriveLedger`;
      description = `${presetA.name} ($${telA.total5YrTcoUsd.toLocaleString()} 5-yr TCO, ${telA.reliabilityScore}/100 reliability) vs ${presetB.name} ($${telB.total5YrTcoUsd.toLocaleString()} 5-yr TCO, ${telB.reliabilityScore}/100 reliability). ${cheaperName} saves $${delta5Yr.toLocaleString()} over 5 years.`;
    }

    addRoute({
      path: matchup.path,
      title,
      description,
      canonicalUrl: `${SITE_ORIGIN}${matchup.path}`,
    });
  }

  // 5. Powertrain-Validated Vehicle × OBD-II Pages
  const obdMap = new Map(OBD_CODES.map((c) => [c.code, c]));
  const fullObdMatrix = generateFullVehicleObdMatrix();
  const targetObdEntries = includeAllObd
    ? fullObdMatrix
    : fullObdMatrix.filter((item) => item.isKnownWeakPoint);

  for (const item of targetObdEntries) {
    const preset = presetMap.get(item.presetId);
    const dossier = obdMap.get(item.code);
    if (!preset || !dossier) continue;

    const minParts = dossier.partsCostRangeUsd?.[0] ?? 95;
    const maxParts = dossier.partsCostRangeUsd?.[1] ?? 1650;
    const minLabor = dossier.laborHoursRange?.[0] ?? 1.0;
    const maxLabor = dossier.laborHoursRange?.[1] ?? 4.0;
    const codeLower = dossier.code.toLowerCase();

    const title = `${preset.name} ${dossier.code} ${dossier.title}: Repair Cost & Live PID Guide | DriveLedger`;
    const description = `Diagnose ${dossier.code} (${dossier.title}) on the ${preset.name} (${preset.engineCode}). Compare Dealership vs Independent vs DIY repair costs ($${minParts}–$${maxParts} parts, ${minLabor}–${maxLabor}h labor) and run First-Principles OBD-II Live PID telemetry checks.`;

    addRoute({
      path: `/obd/${preset.id}/${codeLower}`,
      title,
      description,
      canonicalUrl: `${SITE_ORIGIN}/obd/${preset.id}/${codeLower}`,
    });
  }

  return routes;
}

/**
 * Runs the static prerendering process on distDir using baseTemplate.
 */
export async function prerenderSeoRoutes(options = {}) {
  const distDir = options.distDir || DIST_DIR;
  const templatePath = path.join(distDir, 'index.html');

  if (!fs.existsSync(templatePath)) {
    throw new Error(
      `[Prerender] Base template not found at ${templatePath}. Run 'vite build' first.`
    );
  }

  const startTime = Date.now();
  const baseTemplate = fs.readFileSync(templatePath, 'utf8');

  // 1. Ingest all SEO routes
  const routes = collectAllSeoRoutes(options);

  // 2. Directory cache to prevent repeated filesystem syscalls
  const ensuredDirs = new Set();
  function ensureDir(dirPath) {
    if (ensuredDirs.has(dirPath)) return;
    fs.mkdirSync(dirPath, { recursive: true });
    ensuredDirs.add(dirPath);
  }

  // 3. Update root dist/index.html with default OpenGraph and Twitter tags
  const rootHtml = injectRouteMetadata(baseTemplate, {
    title: 'DriveLedger — Independent Automotive Cost Intelligence',
    description:
      '5-year ownership costs, upcoming repairs, and fair workshop prices for any check-engine code. Independent automotive cost platform.',
    canonicalUrl: `${SITE_ORIGIN}/`,
  });
  fs.writeFileSync(templatePath, rootHtml, 'utf8');

  // 4. Prerender each static route into dist/<route>/index.html
  let writtenCount = 0;
  for (const route of routes) {
    const destFile = routePathToDistFile(distDir, route.path);
    ensureDir(path.dirname(destFile));
    const renderedHtml = injectRouteMetadata(baseTemplate, route);
    fs.writeFileSync(destFile, renderedHtml, 'utf8');
    writtenCount++;
  }

  const elapsedMs = Date.now() - startTime;
  console.log(
    `[Prerender] Successfully prerendered ${writtenCount} static SEO routes into ${distDir} in ${elapsedMs}ms`
  );

  return {
    totalRoutes: writtenCount,
    elapsedMs,
  };
}

// CLI execution check
const isDirectCli = process.argv[1] && path.resolve(process.argv[1]) === __filename;
if (isDirectCli) {
  prerenderSeoRoutes().catch((err) => {
    console.error('[Prerender] Execution failed:', err);
    process.exit(1);
  });
}
